CREATE TABLE USER_PATH_INFO (
    USER_ID VARCHAR(100),
    MOVEMENT_ID VARCHAR(100),
    START_POINT GEOMETRY(Point, 4326),
    END_POINT GEOMETRY(Point, 4326),
    START_DTM TIMESTAMP,
    END_DTM TIMESTAMP,
    MOVE_KM DOUBLE PRECISION,
    PRIMARY KEY (USER_ID, MOVEMENT_ID) 
);


-- 시설명	위도	경도	우편번호	도로명주소	전화번호	홈페이지	휴무일	운영시간	주차가능여부	입장(이용료)가격정보
CREATE TABLE STORE_INFO (
	ID SERIAL PRIMARY KEY,
	STORE_NAME VARCHAR(200),
  TYPE_NM VARCHAR(30),
	LATITUDE DOUBLE PRECISION NOT NULL,
	LONGITUDE DOUBLE PRECISION NOT NULL,
	POST_NUM VARCHAR(6),
  ADDRESS VARCHAR(300),
  PHONE_NUM VARCHAR(20),
  WEB_SITE VARCHAR(500),
  DAY_OFF VARCHAR(50),
  OPERATING_HOURS VARCHAR(300),
  PARKING_YN VARCHAR(1),
  PRICE_NUM VARCHAR(50),
	REG_DTM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UPDATE_DTM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX IDX_STORE_LAT_LONG ON STORE_INFO (LATITUDE, LONGITUDE);
ALTER TABLE store_info
ADD COLUMN geom geography(Point, 4326) GENERATED ALWAYS AS (
    ST_SetSRID(ST_Point(LONGITUDE, LATITUDE), 4326)::geography
) STORED;



CREATE TABLE USER_PATH_POINTS (
    USER_ID VARCHAR(100),
    MOVEMENT_ID VARCHAR(100), -- 새롭게 추가된 이동 ID
    POINT GEOMETRY(Point, 4326),
    TIME TIMESTAMP,
    SPEED DOUBLE PRECISION,
    SEQUENCE INT, -- 지점 순서
    PRIMARY KEY (USER_ID, MOVEMENT_ID, SEQUENCE) -- 복합 키로 USER_ID, MOVEMENT_ID, SEQUENCE를 사용
);

CREATE TABLE TRAFFIC_ALERT (
	ID VARCHAR(100) NOT NULL,
	ADDRESS VARCHAR(200) NULL,
	TITLE VARCHAR(500) NULL,
	TYPE_CD VARCHAR(4) NOT NULL,
	SUB_CD VARCHAR(4) NOT NULL,
	LATITUDE DOUBLE PRECISION NOT NULL,
	LONGITUDE DOUBLE PRECISION NOT NULL,
	START_DTM TIMESTAMP NULL,
	END_DTM TIMESTAMP NULL,
	UPDATE_DTM TIMESTAMP NULL,
	CONSTRAINT PK_TRAFFIC_ALERT PRIMARY KEY (ID)
);

CREATE INDEX IDX_TRAFFIC_ALERT_GEO ON TRAFFIC_ALERT (LATITUDE, LONGITUDE);

CREATE TABLE WALK_ALERT (
	ID INTEGER PRIMARY KEY,
	ADDRESS VARCHAR(200),
	YEAR VARCHAR(4),
	OCCXRRNC_CNT INT,
	LATITUDE DOUBLE PRECISION NOT NULL,
	LONGITUDE DOUBLE PRECISION NOT NULL,
	REG_DTM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX IDX_LAT_LONG ON WALK_ALERT (LATITUDE, LONGITUDE);



CREATE TABLE CCTV_INFO (
	ID VARCHAR(20) PRIMARY KEY,
	CCTV_NM VARCHAR(100),
  CENTER_NM VARCHAR(50),
	LATITUDE DOUBLE PRECISION NOT NULL,
	LONGITUDE DOUBLE PRECISION NOT NULL,
	REG_DTM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX IDX_CCTV_LAT_LONG ON CCTV_INFO (LATITUDE, LONGITUDE);

